/* Estilos para o cabeçalho da página */
.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}

.btn {
  padding: 0.8rem 1.5rem;
  border: none;
  border-radius: 0.5rem;
  cursor: pointer;
  font-size: 1rem;
  font-weight: 500;
  transition: background-color 0.3s ease;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.btn-primary {
  background-color: var(--color-primary);
  color: white;
}

.btn-primary:hover {
  background-color: #5a67d8;
}

/* Container de Pesquisa */
.search-container {
  background-color: #fff;
  padding: 2rem;
  border-radius: 1rem;
  box-shadow: var(--box-shadow);
  margin-bottom: 2rem;
}

.search-form {
  display: flex;
  gap: 1rem;
}

.search-input {
  flex-grow: 1;
  padding: 0.8rem;
  border: 1px solid #ccc;
  border-radius: 0.5rem;
  font-size: 1rem;
}

/* Container de Resultados */
.results-container {
  margin-top: 2rem;
}

.results-container h2 {
  margin-bottom: 1rem;
  color: var(--color-dark);
}

/* Estilos da Tabela (reutilizados) */
.table-container {
  background-color: #fff;
  padding: 2rem;
  border-radius: 1rem;
  box-shadow: var(--box-shadow);
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

table th, table td {
  padding: 1rem;
  border-bottom: 1px solid #eee;
}

table th {
  color: var(--nav-link-color);
  font-weight: 600;
  text-transform: uppercase;
  font-size: 0.85rem;
}

table td {
  color: var(--color-dark);
}

table tbody tr:last-child td {
  border-bottom: none;
}
